tool_input_args.value:
node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Order
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get('ORD-F15D7C');
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Order Items
const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all('ORD-F15D7C');
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get product details for each item
const productIds = [...new Set(items.map(i => i.product_id))];
console.log('\n=== PRODUCTS ===');
for (const pid of productIds) {
  const product = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  console.log(JSON.stringify(product, null, 2));
  const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(pid);
  console.log('Variants:', JSON.stringify(variants, null, 2));
}

// Fulfillments
const fulfillments = db.prepare('SELECT * FROM order_fulfillments WHERE order_id = ?').all('ORD-F15D7C');
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));

// Payments
const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all('ORD-F15D7C');
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Customer info
if (order) {
  const user = db.prepare('SELECT * FROM users WHERE user_id = ?').get(order.customer_id);
  console.log('\n=== CUSTOMER ===');
  console.log(JSON.stringify(user, null, 2));
  const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id = ?').all(order.customer_id);
  console.log('\n=== PAYMENT METHODS ===');
  console.log(JSON.stringify(pms, null, 2));
}

db.close();
"
